"""Additional public sections; imported by build.py."""
import urllib.parse
def extra_pages(g):
 page,intro,button,e,ARROW,CFG,S=(g[k] for k in ['page','intro','button','e','ARROW','CFG','S'])
 # Contractor information is factual; unavailable certificate scans are requested from a manager.
 body=intro('Для генподрядчиков','Ресурсы под ваш<br>строительный график.','Подключаемся к фасадному комплексу целиком или к отдельному этапу. Обсуждаем объёмы, готовность площадки и последовательность работ.')
 body+='''<section class="section contractor-resources"><div><strong>180</strong><p>монтажников-фасадчиков</p></div><div><strong>63</strong><p>собственных фасадных подъёмника</p></div><div><strong>12</strong><p>руководителей проектов и заместителей</p></div></section>'''
 body+='<section class="section contractor-grid"><div><p class="eyebrow">Формат сотрудничества</p><h2>Подключаемся<br>к вашей задаче.</h2><ul class="numbered-list"><li><span>01</span>Монтаж по готовой проектной документации</li><li><span>02</span>Производство, комплектация и поставка конструкций</li><li><span>03</span>Инженерная подготовка и организация монтажа</li><li><span>04</span>Ремонт существующих фасадов и работы на высоте</li></ul></div><aside class="brief-panel"><p class="eyebrow">Запрос коммерческого предложения</p><h3>Исходные данные</h3><ul><li>Адрес и назначение объекта</li><li>Чертежи, спецификация или ведомость объёмов</li><li>Высота и условия доступа к фасаду</li><li>Планируемый срок начала и очередность работ</li><li>Контакт ответственного специалиста</li></ul>'+button('Запросить КП','quote.html')+'</aside></section>'
 body+='<section class="section contractor-documents"><div><p class="eyebrow">Для проверки подрядчика</p><h2>Документы<br>и опыт.</h2><p>Портфолио доступно для скачивания. Документы СРО, лицензию МЧС и дополнительные сведения о компании предоставим по запросу.</p></div><div class="document-links"><a class="document-card portfolio-download" href="downloads/portfolio.pdf" download><span>Портфолио ФАСАД.PRO<small>Объекты · Команда · Техника / PDF</small></span>'+ARROW+'</a><a class="document-card" href="contacts.html"><span>Реквизиты компании<small>Юридическое лицо · ИНН · КПП</small></span>'+ARROW+'</a><a class="document-card" href="__DOCUMENTS_MAIL__"><span>Запросить документы<small>СРО · Лицензия МЧС · Сведения для тендера</small></span>'+ARROW+'</a></div></section>'
 body+='<section class="section contractor-geography"><p class="eyebrow">Организация выхода</p><h2>Работаем по всей России.</h2><p>Офисы в Москве и Владивостоке. Условия мобилизации, размещения команды, доставки техники и снабжения согласуем для конкретной площадки.</p>'+button('Обсудить объект','request.html')+'</section>'
 body=body.replace('__DOCUMENTS_MAIL__','mailto:'+e(CFG['email'])+'?subject='+urllib.parse.quote('Запрос документов компании ФАСАД.PRO'))
 page('contractors.html','Для генподрядчиков','Фасадный подряд: команда, техника, документация, портфолио и запрос коммерческого предложения.',body,'contractors')
 choices=''.join(f'<label class="choice-tile"><input type="checkbox" name="service" value="{s["id"]}"><span>{s["title"]}</span></label>' for s in S)
 for kind in ['request','quote']:
  quote=kind=='quote';title='Запрос коммерческого предложения' if quote else 'Обсудить проект'
  steps='<ol class="request-steps" aria-label="Этапы заявки"><li aria-current="step"><span>01</span>Объект и работы</li><li><span>02</span>Параметры и файлы</li><li><span>03</span>Контакты и отправка</li></ol>'
  hero=f'<section class="page-intro request-intro"><p class="eyebrow">{title}</p><div class="intro-grid"><h1>{"Исходные данные<br>для вашего КП." if quote else "Расскажите<br>о вашем объекте."}</h1><p>{"Приложите проект или ведомость объёмов. Подготовим предложение после изучения документации." if quote else "Выберите направления работ, опишите задачу и приложите материалы. Менеджер получит заявку и свяжется с вами."}</p></div></section>'
  extra='<div class="field-grid"><label>Высота / этажность<input name="height" maxlength="80" placeholder="Например, 12 этажей"></label><label>Система / материал<input name="system" maxlength="150" placeholder="Алюминий, ПВХ, тип системы"></label></div><label>Желаемая дата получения КП <span class="optional">необязательно</span><input name="deadline" type="date"></label>' if quote else ''
  form=f'''<section class="section request-section"><div class="request-layout"><aside class="request-aside">{steps}<div class="request-help"><p>Обсудить голосом</p><a href="tel:{''.join(c for c in CFG['phone'] if c in '+0123456789')}">{e(CFG['phone'])}</a><span>{e(CFG['manager'])}</span></div><p class="privacy-note">Заявка и вложения доступны сотрудникам, которые готовят предложение. <a href="privacy.html">Как обрабатываются данные</a></p></aside><div><p class="form-connection" id="form-connection" role="status">Проверяем возможность отправки…</p><noscript>Для формы нужен JavaScript. Свяжитесь с менеджером: <a href="mailto:{e(CFG['email'])}">{e(CFG['email'])}</a>.</noscript><form id="request-form" class="js-only" data-kind="{kind}" novalidate><input type="hidden" name="kind" value="{kind}"><input type="hidden" name="solution" value=""><div id="solution-context" class="solution-context" hidden></div><div class="honey-field" aria-hidden="true"><label>Ваш сайт<input name="website" autocomplete="off" tabindex="-1"></label></div><fieldset class="request-step" data-step="0"><legend>Какие работы нужны?</legend><p class="field-hint">Можно выбрать несколько направлений.</p><div class="choice-grid">{choices}</div><p class="field-error" id="service-error" hidden>Выберите хотя бы одно направление.</p><div class="field-grid"><label>Тип объекта<select name="object" required><option value="">Выберите тип</option><option>Жилой комплекс</option><option>Гостиница</option><option>Общественное здание</option><option>Коммерческое здание</option><option>Частный объект</option><option>Другой объект</option></select></label><label>Город / расположение<input name="city" maxlength="120" autocomplete="address-level2" required placeholder="Город и адрес объекта"></label></div></fieldset><fieldset class="request-step" data-step="1" hidden><legend>Параметры и материалы</legend><p class="field-hint">Укажите известные данные. Остальное уточним при обсуждении.</p><div class="field-grid"><label>Площадь работ, м² <span class="optional">необязательно</span><input name="area" type="number" min="1" max="10000000" step="any" inputmode="decimal" placeholder="Например, 2500"></label><label>Планируемое начало<select name="timing"><option>Нужно обсудить</option><option>В ближайший месяц</option><option>В течение 1–3 месяцев</option><option>Позже 3 месяцев</option></select></label></div>{extra}<label>Документация<select name="documents"><option>Есть проект и спецификации</option><option>Есть часть документации</option><option>Есть фотографии / эскизы</option><option selected>Пока нет, нужно обсудить</option></select></label><label>Описание задачи<textarea name="comment" rows="4" maxlength="3000" placeholder="Объём, состояние фасада, готовность площадки, ограничения по доступу…"></textarea></label><div class="upload-zone" id="upload-zone"><label for="request-files"><strong>Приложить проект и фотографии</strong><span>Выберите файлы или перетащите их сюда</span></label><input id="request-files" type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.webp,.dwg,.dxf,.xlsx,.docx,.txt,.zip" aria-describedby="upload-hint"><p id="upload-hint">До 5 файлов. Каждый — до 10 МБ, суммарно — до 25 МБ. PDF, фото, DWG, DXF, XLSX, DOCX, TXT, ZIP.</p></div><ul id="selected-files" aria-label="Прикреплённые файлы"></ul><p id="upload-error" class="field-error" role="status"></p></fieldset><fieldset class="request-step" data-step="2" hidden><legend>Контакты и отправка</legend><div class="field-grid"><label>Ваше имя<input name="name" maxlength="100" autocomplete="name" required></label><label>Компания {'' if quote else '<span class="optional">необязательно</span>'}<input name="company" maxlength="150" autocomplete="organization" {'required' if quote else ''} placeholder="{'Название или «Частный заказчик»' if quote else 'Название компании'}"></label></div><p class="field-hint">Укажите телефон или email — достаточно одного контакта.</p><div class="field-grid"><label>Телефон<input name="phone" type="tel" maxlength="40" autocomplete="tel" placeholder="+7 ___ ___ __ __"></label><label>Email<input name="email" type="email" maxlength="200" autocomplete="email" placeholder="name@company.ru"></label></div><p id="contact-error" class="field-error" hidden>Укажите телефон или email.</p><div class="request-review"><h3>Проверьте заявку</h3><dl id="request-summary"></dl><button class="text-button" type="button" data-edit-request>Изменить исходные данные</button></div><label class="consent-check"><input type="checkbox" name="consent" value="yes" required><span>Согласен на обработку данных заявки {e(CFG['legalName'])} для связи со мной и подготовки предложения. <a href="privacy.html" target="_blank" rel="noopener">Условия обработки</a></span></label></fieldset><div class="form-actions"><button type="button" class="text-button" id="request-back" hidden>← Назад</button><button type="submit" class="button" id="request-next">Далее</button></div><p class="form-status" role="status" aria-live="polite"></p></form><section id="request-result" hidden aria-labelledby="result-title"><p class="eyebrow" id="result-eyebrow">ФАСАД.PRO</p><h2 id="result-title" tabindex="-1"></h2><p id="result-description"></p><p class="result-note" id="result-reference"></p><div id="offline-draft" hidden><label>Текст заявки<textarea id="email-draft" rows="13" readonly></textarea></label><div class="result-actions"><a class="button" id="open-mail" href="mailto:{e(CFG['email'])}">Открыть почту</a><button class="button button-outline" id="copy-draft" type="button">Скопировать</button><button class="text-button" id="download-draft" type="button">Скачать .txt</button></div><p id="draft-status" role="status"></p><button class="text-button" id="edit-draft" type="button">← Вернуться к редактированию</button></div><a class="text-button" id="after-submit" href="projects.html" hidden>Посмотреть проекты {ARROW}</a></section></div></div></section>'''
  form+=g['release4'].data_element({'solutions':__import__('json').loads((g['ROOT']/'source/solutions.json').read_text())})
  page(kind+'.html',title,'Заявка на фасадные работы с проектной документацией, объёмами, сроками и контактами.',hero+form)
 privacy=f'''<section class="page-intro"><p class="eyebrow">Данные посетителей / 23.09.2026</p><h1 class="policy-title">Обработка данных</h1></section><section class="section policy-content"><h2>Кто обрабатывает данные</h2><p>{e(CFG['legalName'])}, ИНН {e(CFG['inn'])}, КПП {e(CFG['kpp'])}. Для вопросов, исправления или удаления данных: <a href="mailto:{e(CFG['email'])}">{e(CFG['email'])}</a>.</p><h2>Заявки и документы</h2><p>При отправке формы мы получаем указанные вами имя, компанию, телефон или email, сведения об объекте и прикреплённые файлы. Они используются для ответа на обращение, изучения задачи и подготовки коммерческого предложения. Поля со знаком «необязательно» можно оставить пустыми. Для связи достаточно одного контакта — телефона или email.</p><p>Заявки доступны авторизованным сотрудникам. Файлы не размещаются в открытом доступе. Уведомления о заявках отправляются по почте; если вы указали email, на него может прийти подтверждение получения. Рекламная рассылка по данным этой формы не выполняется.</p><p>Заявки в журнале сайта хранятся до 180 дней, затем автоматически удаляются вместе с вложениями. Документы, отдельно переданные в рамках заключённого договора, обрабатываются в рамках соответствующих отношений. Для отзыва согласия или удаления обращения напишите на указанный email и сообщите номер заявки либо контакт, оставленный в форме.</p><h2>Необязательная статистика</h2><p>Только с вашего разрешения сайт учитывает просмотры страниц, выбранные направления, начало и этапы заполнения формы, обращения по телефону и почте, скачивание портфолио. Содержание полей и файлов в статистику не передаётся. Используется случайный идентификатор посещения. Адреса страниц учитываются без поисковых параметров; источник перехода — без полного адреса внешней страницы.</p><p>События статистики хранятся 90 дней. Выбор о статистике сохраняется в браузере, идентификатор посещения — в рамках сеанса. Изменить выбор можно кнопкой «Статистика» внизу любой страницы. Сторонние рекламные счётчики не используются.</p><h2>Технические данные</h2><p>Для ограничения спама и попыток входа сервер временно учитывает необратимый код сетевого адреса. В панели управления используется защищённая cookie сессии со сроком до 8 часов. Эти функции необходимы для работы и защиты сервиса.</p><h2>Карта проектов</h2><p>Карта улиц OpenStreetMap загружается только по кнопке «Показать карту улиц». При загрузке браузер обращается к серверу карт и передаёт технические данные, необходимые для получения изображений. Можно пользоваться списком проектов без загрузки карты.</p><h2>Персональное портфолио</h2><p>Название получателя используется только для формирования запрошенного PDF и не сохраняется в журнале заявок. Вы можете оставить это поле пустым.</p><h2>Ваш выбор</h2><p>Вы можете пользоваться сайтом без необязательной статистики, связаться по телефону вместо формы, запросить исправление или удаление данных. Нажимая «Отправить заявку» с отмеченным согласием, вы разрешаете обработать сведения для ответа на ваше обращение и подготовки предложения.</p></section>'''
 page('privacy.html','Обработка данных','Обработка заявок, вложений и добровольной статистики посещений.',privacy)
